// Exact-output tests against fixtures generated by a C build of the original AGI
// interpreter's line and brush routines (Sarien/NAGI lineage). The generator is not
// shipped; the fixtures pin every pixel, in drawing order.
import { describe, expect, it } from 'vitest';
import { plotPen, type PenShape } from '../../src/engine/brush.ts';
import { PIC_HEIGHT, PIC_WIDTH } from '../../src/engine/framebuffer.ts';
import { linePixels } from '../../src/engine/line.ts';
import oracle from '../fixtures/agi-oracle.json';

interface LineCase { from: [number, number]; to: [number, number]; pixels: Array<[number, number]> }
interface BrushCase { size: number; shape: PenShape; splatter: boolean; texture: number; at: [number, number]; pixels: Array<[number, number]> }

describe('AGI oracle: lines', () => {
  it.each((oracle.lines as LineCase[]).map((c) => [`${c.from} → ${c.to}`, c] as const))('%s', (_, c) => {
    expect(linePixels(c.from[0], c.from[1], c.to[0], c.to[1])).toEqual(c.pixels);
  });
});

describe('AGI oracle: brushes', () => {
  const cases = oracle.brushes as BrushCase[];
  it.each(cases.map((c) => [`size ${c.size} ${c.shape}${c.splatter ? ` splatter t${c.texture}` : ''} @${c.at}`, c] as const))('%s', (_, c) => {
    const px: Array<[number, number]> = [];
    plotPen({ size: c.size, shape: c.shape, splatter: c.splatter }, c.at[0], c.at[1], c.texture, (x, y) => {
      if (x >= 0 && y >= 0 && x < PIC_WIDTH && y < PIC_HEIGHT) px.push([x, y]);
    });
    expect(px).toEqual(c.pixels);
  });
});
